from collect import append_tag

def test_no_leak_between_calls():
    first = append_tag("a")
    second = append_tag("b")
    assert first == ["a"]
    assert second == ["b"]

def test_explicit_list_reused():
    box = ["x"]
    assert append_tag("y", box) == ["x", "y"]


from parsing import parse_kv

def test_kv_spaces():
    assert parse_kv(" a = 1 , b = 2 ") == {"a": "1", "b": "2"}

def test_kv_empty_segments():
    assert parse_kv("a=1,,b=2") == {"a": "1", "b": "2"}

def test_kv_value_with_equal():
    assert parse_kv("a=b=c") == {"a": "b=c"}
